import { getImageProps, type ImageLoaderProps } from "next/image";
import manifest from "@/content/images.manifest.json";

/**
 * Every photo is pre-generated by scripts/images.mjs (AVIF + WebP at fixed widths, hashed names) and
 * served as a static file. A per-slot loader maps next/image's requested width to the nearest file, so
 * the very first, cold visit never waits on a runtime image optimiser.
 */
export type SlotEntry = {
  v: string;
  width: number;
  height: number;
  widths: number[];
  blur: string;
  focal: [number, number];
  alt: string;
  xray?: { widths: number[] };
  car?: { x0: number; y0: number; x1: number; y1: number };
};

export type SlotName =
  | "hero-desktop"
  | "hero-mobile"
  | "pdi-delivery-bay"
  | "preowned-inspection"
  | "obd-scan-closeup"
  | "paint-gauge-macro"
  | "underbody-inspection"
  | "inspector-portrait";

const entries = manifest as unknown as Partial<Record<SlotName, SlotEntry>>;

export const getSlot = (name: SlotName): SlotEntry | undefined => entries[name];

const pick = (widths: number[], w: number) => widths.find((x) => x >= w) ?? widths[widths.length - 1];

export function slotLoader(name: SlotName, entry: SlotEntry, format: "avif" | "webp", variant: "" | "-xray" = "") {
  return ({ width }: ImageLoaderProps) => `/images/${name}/${name}${variant}-${pick(entry.widths, width)}.${entry.v}.${format}`;
}

/** Collapses srcset entries that resolve to the same file and labels each with the file's real width. */
function tidySrcSet(srcSet: string | undefined) {
  if (!srcSet) return srcSet;
  const files = new Map<string, number>();
  for (const entry of srcSet.split(", ")) {
    const url = entry.split(" ")[0];
    const width = Number(url.match(/-(\d+)\.[0-9a-f]+\.(?:avif|webp)$/)?.[1]);
    if (url && width && !files.has(url)) files.set(url, width);
  }
  return [...files].map(([url, width]) => `${url} ${width}w`).join(", ");
}

type SourceOptions = {
  sizes: string;
  variant?: "" | "-xray";
  alt?: string;
  loading?: "eager" | "lazy";
  fetchPriority?: "high" | "low" | "auto";
};

/** AVIF + WebP props for one slot, ready for a <picture>. Returns null when the source image is missing. */
export function slotSources(name: SlotName, opts: SourceOptions) {
  const entry = getSlot(name);
  if (!entry) return null;
  const base = {
    src: `/images/${name}`,
    width: entry.width,
    height: entry.height,
    sizes: opts.sizes,
    alt: opts.alt ?? entry.alt,
    loading: opts.loading,
    fetchPriority: opts.fetchPriority,
  };
  const avif = getImageProps({ ...base, loader: slotLoader(name, entry, "avif", opts.variant) }).props;
  const webp = getImageProps({ ...base, loader: slotLoader(name, entry, "webp", opts.variant) }).props;
  avif.srcSet = tidySrcSet(avif.srcSet);
  webp.srcSet = tidySrcSet(webp.srcSet);
  return { entry, avif, webp };
}

export const focalPosition = (entry: SlotEntry) => `${(entry.focal[0] * 100).toFixed(1)}% ${(entry.focal[1] * 100).toFixed(1)}%`;
